local D=Config.Delivery
local function auth(s)local ok,l=pcall(function()return exports.cookie_admin:getEffectiveLevel(s)end)return ok and(tonumber(l)or 0)>=3 end
CreateThread(function()
 MySQL.query.await([[CREATE TABLE IF NOT EXISTS cookie_delivery_restaurant(id INT AUTO_INCREMENT PRIMARY KEY,npc_id INT NOT NULL,label VARCHAR(80) NOT NULL,pickup_x DOUBLE NOT NULL,pickup_y DOUBLE NOT NULL,pickup_z DOUBLE NOT NULL,base_pay BIGINT NOT NULL DEFAULT 15000,per_km BIGINT NOT NULL DEFAULT 10000,is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4]])
 MySQL.query.await([[CREATE TABLE IF NOT EXISTS cookie_delivery_dropoff(id INT AUTO_INCREMENT PRIMARY KEY,npc_id INT NOT NULL,label VARCHAR(80) NOT NULL,x DOUBLE NOT NULL,y DOUBLE NOT NULL,z DOUBLE NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4]])
end)
local function data(n)return{npcId=tonumber(n),restaurants=MySQL.query.await('SELECT * FROM cookie_delivery_restaurant WHERE npc_id=? AND is_active=1 ORDER BY id',{tonumber(n)})or{},dropoffs=MySQL.query.await('SELECT * FROM cookie_delivery_dropoff WHERE npc_id=? AND is_active=1 ORDER BY id',{tonumber(n)})or{}}end
local function push(s,n)TriggerClientEvent('cookie_delivery:client:adminData',s,data(n))end
RegisterNetEvent('cookie_delivery:server:adminList',function(n)local s=source if auth(s)then push(s,n)end end)
RegisterNetEvent('cookie_delivery:server:addRestaurant',function(d)local s=source;if not auth(s)or type(d)~='table'then return end;local p=GetEntityCoords(GetPlayerPed(s));MySQL.insert.await('INSERT INTO cookie_delivery_restaurant(npc_id,label,pickup_x,pickup_y,pickup_z,base_pay,per_km) VALUES(?,?,?,?,?,?,?)',{tonumber(d.npcId),tostring(d.label or'식당'),p.x,p.y,p.z,tonumber(d.basePay)or D.DefaultBasePay,tonumber(d.perKm)or D.DefaultPerKm});push(s,d.npcId)end)
RegisterNetEvent('cookie_delivery:server:addDropoff',function(d)local s=source;if not auth(s)or type(d)~='table'then return end;local p=GetEntityCoords(GetPlayerPed(s));MySQL.insert.await('INSERT INTO cookie_delivery_dropoff(npc_id,label,x,y,z) VALUES(?,?,?,?,?)',{tonumber(d.npcId),tostring(d.label or'고객'),p.x,p.y,p.z});push(s,d.npcId)end)
RegisterNetEvent('cookie_delivery:server:deleteRestaurant',function(d)local s=source;if auth(s)then MySQL.update.await('UPDATE cookie_delivery_restaurant SET is_active=0 WHERE id=? AND npc_id=?',{tonumber(d.id),tonumber(d.npcId)});push(s,d.npcId)end end)
RegisterNetEvent('cookie_delivery:server:deleteDropoff',function(d)local s=source;if auth(s)then MySQL.update.await('UPDATE cookie_delivery_dropoff SET is_active=0 WHERE id=? AND npc_id=?',{tonumber(d.id),tonumber(d.npcId)});push(s,d.npcId)end end)

RegisterNetEvent('cookie_delivery:server:updateRestaurant',function(d)local s=source;if not auth(s)or type(d)~='table'then return end;MySQL.update.await('UPDATE cookie_delivery_restaurant SET label=?,base_pay=?,per_km=? WHERE id=? AND npc_id=?',{tostring(d.label or '식당'),tonumber(d.basePay)or D.DefaultBasePay,tonumber(d.perKm)or D.DefaultPerKm,tonumber(d.id),tonumber(d.npcId)});push(s,d.npcId)end)
RegisterNetEvent('cookie_delivery:server:setRestaurantCoord',function(d)local s=source;if not auth(s)or type(d)~='table'then return end;local p=GetEntityCoords(GetPlayerPed(s));MySQL.update.await('UPDATE cookie_delivery_restaurant SET pickup_x=?,pickup_y=?,pickup_z=? WHERE id=? AND npc_id=?',{p.x,p.y,p.z,tonumber(d.id),tonumber(d.npcId)});push(s,d.npcId)end)
RegisterNetEvent('cookie_delivery:server:updateDropoff',function(d)local s=source;if not auth(s)or type(d)~='table'then return end;MySQL.update.await('UPDATE cookie_delivery_dropoff SET label=? WHERE id=? AND npc_id=?',{tostring(d.label or '고객'),tonumber(d.id),tonumber(d.npcId)});push(s,d.npcId)end)
RegisterNetEvent('cookie_delivery:server:setDropoffCoord',function(d)local s=source;if not auth(s)or type(d)~='table'then return end;local p=GetEntityCoords(GetPlayerPed(s));MySQL.update.await('UPDATE cookie_delivery_dropoff SET x=?,y=?,z=? WHERE id=? AND npc_id=?',{p.x,p.y,p.z,tonumber(d.id),tonumber(d.npcId)});push(s,d.npcId)end)
